"""Reviewed Magebean-only action guidance. Criteria and historical results are unchanged."""
import json
from pathlib import Path
base=Path(__file__).resolve().parents[1]/'src/Rules/requirements'
# Each recipe states a concrete change and a verification target, never an automatic fix.
recipes={
'0001':('Review each reported path with stat and getfacl and identify the deployment owner, PHP/web user and shared groups. Remove other-write permission only from the affected path; use a dedicated writable group or ACL for var, generated and pub/media instead of chmod -R 777.','Verify effective write access as the real web user and rerun the filesystem check; confirm uploads, cache and deployment still work.'),
'0002':('Inspect app/etc/env.php ownership, mode and ACLs without printing its contents. Set its owner/group to the approved deployment model and remove permission bits outside the configured maximum; ensure PHP can still read required configuration.','Compare stat/getfacl output with the finding policy and test the storefront/Admin. Do not change the entire project ownership to satisfy this single-file check.'),
'0003':('Move the reported Git metadata, environment files, database dumps or backups outside pub and any served alias. Add explicit edge/origin access denial for sensitive paths and invalidate any cached exposed artifacts.','Request the previously exposed paths without credentials and confirm denial/absence; rotate credentials if secret contents were exposed.'),
'0004':('Identify the actual PHP/web process user and test access to the reported app, vendor and lib paths, including ACLs and mounts. Restrict that identity from writing code while retaining a separate deployment identity and the required writable runtime directories.','Verify access as the web identity, not the deployment owner; exercise deployment, upload and cache workflows before approval.'),
'0005':('Locate the virtual host or location serving each reported directory. Disable autoindex in nginx or Indexes in Apache for that location, including inherited configuration and CDN behavior.','Request each observed directory again without credentials and verify no file listing is returned; a generic 200 page is not by itself proof of exposure.'),
'0006':('Choose an uncommon Admin frontName and apply it through the supported Magento deployment configuration workflow. Update proxy access rules, monitoring and administrator bookmarks; retain MFA and network restrictions.','Confirm the new Admin route works and common admin/backend routes no longer expose the intended login. A renamed route is not access control.'),
'0007':('Identify native Admin authentication versus active Adobe IMS first. For native authentication, enable Magento_TwoFactorAuth and configure supported provider engines; complete enrollment for every administrator and verify recovery/bypass paths. For IMS, retain identity-provider MFA and enrollment evidence.','Test allowed and unenrolled accounts in staging. Empty force_providers means no forced provider list, not proof that MFA is off; module flags alone cannot verify enforcement.'),
'0009':('Review the resolved admin/security/session_lifetime value and its source. Configure the approved timeout through Stores > Configuration > Advanced > Admin > Security or the managed configuration pipeline; review the Magebean 900-second policy before applying a different organizational threshold.','Start an Admin session, leave it idle beyond the approved timeout, and verify server-side expiry and reauthentication as well as the rerun setting observation.'),
'0010':('Review the real Admin origin, reverse proxy and access paths. Restrict administrative access with a VPN, identity-aware gateway or approved network ACL and review exceptions for authorized operators.','Test allowed and disallowed clients at every Admin origin; retain the effective edge/origin rule and access-test evidence.'),
'0011':('Inspect the reported CAPTCHA/reCAPTCHA and lockout settings in Admin Security and the actual authentication mode. Configure a supported challenge or bounded failed-login count with a positive lockout duration; avoid permanent lockout policies that enable denial of service.','Use a designated staging account to verify repeated failed attempts trigger the configured protection and that legitimate recovery still works.'),
'0014':('Open each reported file and line and trace the superglobal value to its use. In Magento HTTP controllers/services use an injected Magento\\Framework\\App\\RequestInterface to obtain request parameters or headers where appropriate; then apply explicit type, length and allow-list validation. Replacing $_GET with getParam alone does not validate input.','For $_FILES use the supported upload abstraction and verify file type/storage policy; for $_SERVER distinguish trusted server metadata from client-controlled headers. Test missing, malformed and unauthorized input plus the relevant SQL/HTML/path/network sink. Document a narrow justified exception for non-HTTP bootstrap/server metadata rather than blindly replacing every reference.'),
'0015':('Locate the state-changing form or controller. Use Magento form_key generation and validation for browser session requests and supported POST action interfaces; review intentional webhook/API exceptions with their independent authentication.','In staging submit valid, missing and incorrect tokens and confirm only authorized requests change state. A form_key string in source does not prove server-side validation.'),
'0016':('Trace each URL input to the outbound HTTP client. Allow only required schemes, hosts and ports; block private, loopback, link-local and metadata destinations after DNS resolution and revalidate redirects.','Test approved endpoints and denied schemes/internal destinations using controlled staging endpoints; verify redirects and DNS changes cannot bypass the policy.'),
'0019':('Remove eval, executable assert and dynamically constructed PHP execution from the reported code path. Replace dynamic execution with explicit service calls or a fixed dispatch map; treat unexpected executable content as a potential incident.','Test permitted operations and attacker-controlled inputs; confirm no user value can become executable PHP and rerun the source observation.'),
'0020':('Trace the reported filename/path input. Map approved identifiers to server-owned paths, canonicalize existing paths and enforce containment within the approved base directory; reject traversal, absolute paths and unsafe symlinks.','Test ../, encoded traversal, absolute paths and symlink escapes in staging; verify downloads and writes cannot leave the approved directory.'),
'0021':('Use the supported Magento upload abstraction with an explicit extension/MIME allow-list, size limits and server-generated names. Store uploads in a non-executable location and configure the web server to deny execution there; do not trust a client Content-Type header.','Test double extensions, renamed executable files, oversized input and unauthorized upload requests without executing uploaded payloads.'),
'0023':('Replace security-sensitive rand/mt_rand/uniqid identifiers with random_bytes or random_int and suitable encoding. Use supported framework token generation where available; keep non-security simulation randomness separate.','Verify token entropy, collision handling and expiry in the relevant workflow; confirm tokens are not derived from timestamps or predictable identifiers.'),
'0025':('Review each raw crypto/session API call. Prefer the supported Magento encryption, hashing and session services for its purpose and remove custom cryptographic constructions; distinguish password hashing from reversible encryption.','Test compatibility and session behavior in staging, including existing encrypted data and rotation. Do not rotate the Magento encryption key or reencrypt data without a planned supported migration.'),
'0026':('At the actual TLS termination layer configure the HTTP storefront entrypoint to redirect directly to its canonical same-host HTTPS URL. Correct Magento secure base URLs and proxy scheme forwarding so the origin does not create redirect loops.','Request the reported HTTP URL and inspect the first Location header and HTTPS response; test checkout and login behind the real proxy.'),
'0027':('Configure exactly one Strict-Transport-Security header on the successful canonical HTTPS response. Increase max-age to the approved policy after validating HTTPS coverage; Magebean uses 31536000 seconds.','Verify the observed response emits the exact policy. Review all subdomains before adding includeSubDomains and follow a separate deliberate process before enabling preload.'),
'0028':('Disable TLS 1.0 and 1.1 at the CDN/load balancer/origin endpoint identified by the finding while retaining supported TLS 1.2/1.3 configurations. Inventory required client integrations before rollout.','Probe the same public endpoint with legacy and modern TLS clients; modern connections must succeed and legacy negotiation must be rejected.'),
'0029':('Replace the reported HTTP asset URL with its verified HTTPS equivalent or an appropriate same-origin URL. Update theme/module/configuration sources rather than editing generated static files directly.','Redeploy affected static assets and invalidate relevant caches; inspect browser network requests on the affected pages for remaining mixed content.'),
'0030':('Identify the sensitive cookie and the application/proxy layer setting it. Apply Secure and HttpOnly where the cookie is not intentionally needed by JavaScript, and choose SameSite compatible with the authentication/payment flow; SameSite=None requires Secure.','Inspect Set-Cookie on actual authenticated and payment return flows. Confirm login, embedded checkout and logout still work; unrelated public cookies do not prove session-cookie protection.'),
'0031':('Inspect php bin/magento deploy:mode:show and the deployment pipeline. Prepare compilation/static assets and switch the production release to production mode using the supported deployment procedure during an approved release.','Verify effective runtime/environment overrides and smoke-test storefront, Admin and checkout. A persisted MAGE_MODE declaration alone does not prove every worker uses it.'),
'0034':('Investigate the release build for missing generated dependency-injection artifacts. Run php bin/magento setup:di:compile in the build/staging stage with the correct module set and PHP version, then deploy the resulting release atomically.','Confirm compilation succeeds and affected services load in production mode; do not compile as the web user or erase live generated files while traffic is using them.'),
'0035':('Identify the intended storefront/Admin themes and locales and compare them with the reported published artifacts. Build static content through the supported release pipeline and publish assets for every intended scope.','Request representative versioned CSS/JS from the deployed page and confirm nonempty correct content; one artifact does not prove all themes or locales are complete.'),
'0037':('Inspect php bin/magento cache:status and the persisted cache_types.full_page declaration in the intended release. Enable full_page through the supported configuration/CLI workflow after reviewing any deliberate exception.','Rerun the local state check and separately verify actual cache behavior at the configured built-in cache or Varnish layer; cache headers alone do not prove persisted FPC state.'),
'0038':('Review the declared cache backend classes and the deployment architecture. Configure the supported Redis/cache and Varnish arrangement for this Magento version where applicable; separate credentials and namespaces across environments.','Test cache connectivity, invalidation and representative hits/misses; document alternative approved backends rather than treating every architecture as Redis-only.'),
'0039':('Run php bin/magento indexer:status and review the reported indexer IDs and release/database state. Repair the underlying cron, connection or indexing failure before running targeted reindexing through Magento.','Verify each affected indexer returns to the expected state and that price/search/catalog output is correct; avoid blanket reindexing during peak traffic.'),
'0040':('Review the declared Redis session backend and network boundary. Configure authentication/ACLs appropriate to the Redis deployment, protect transport where required and restrict network access; store credentials in protected deployment configuration.','Test session creation, login and failover without printing credentials. Configuration declarations do not prove the live Redis access policy.'),
'0042':('Move the reported log/report directory or symlink outside the served pub tree and remove serving aliases to it. Add origin/edge denial for log/report paths and retain approved private diagnostic access.','Verify affected URLs are inaccessible without authorization and review historical exposure for sensitive log contents before rotating affected secrets.'),
'0043':('Locate the log producer and configure host logrotate, container log retention or the managed logging equivalent for the actual paths. Set retention, compression and ownership suitable for the application and compliance policy.','Verify scheduled rotation and retention occur, the process can reopen/write logs, and disk usage remains bounded; preserve investigation evidence.'),
'0046':('Review the installed scheduler for the deployment owner, or the Adobe Cloud/container/external scheduler definition. Configure the supported Magento cron:run invocation for this release and account for paths, PHP binary and required job groups.','Retain the installed schedule and recent cron_schedule success evidence. A repository deployment script alone is not an installed scheduler.'),
'0047':('Inspect the recorded cron heartbeat and php bin/magento cron:run scheduler environment. Check process permissions, PHP binary, database connectivity, cron group failures and logs before restoring the scheduler.','Confirm a new successful execution timestamp within the configured 900-second observation policy; an external scheduler needs equivalent timestamped evidence.'),
'0048':('Inspect the overdue pending cron jobs by job_code, scheduled_at and status. Repair the job or worker causing backlog and adjust capacity/scheduling with the application owner; do not delete cron_schedule rows just to clear the check.','Observe backlog drain below the configured threshold and verify important email, indexing and cleanup jobs complete successfully.'),
'0049':('For each reported package/version/advisory, confirm applicability and any verified vendor hotfix. Select a vendor-supported fixed version compatible with Magento/PHP and update only the relevant dependencies in a reviewed branch.','Commit the resolved composer.lock, run integration/checkout tests and deploy through the release pipeline; rerun with fresh advisory data and verify the installed version or supported fix evidence.'),
'0050':('Match the detected Magento edition and release branch to current Adobe security release guidance. Plan the supported security patch/upgrade or verified isolated hotfix for the reported advisory; use a documented temporary mitigation only while the permanent fix is scheduled.','Validate the installed release/hotfix artifact after deployment and rerun with current Adobe data. A WAF rule or version string alone is not proof every advisory is fixed.'),
'0051':('Assign an owner and due date to each applicable dependency advisory. Record the selected fixed version or vendor-supported mitigation, compatibility blockers, deployment plan and residual risk.','Validate the actual deployed resolution and attach fresh advisory/lockfile evidence; a plan without deployment does not close the vulnerability.'),
'0052':('For each enabled high-risk module, confirm a business owner, need, supported version and vendor maintenance status. Upgrade to a supported version or remove/disable an unnecessary module through the supported module/dependency release workflow.','Test dependent checkout/Admin/integration functions and verify the module is absent or maintained in the deployed release.'),
'0053':('Record each temporary mitigation with affected issue, scope, owner, expiry, verification and permanent-fix deadline. Verify the mitigation is actually active at the edge/application boundary it claims to protect.','Retest the affected path and retire the exception after the permanent fix; a document or keyword alone does not establish protection.'),
'0054':('Confirm each known-exploited advisory applies to the installed package and review exposure and compromise indicators. Prioritize a supported fix with incident-response ownership; use a tested temporary containment only while deploying the fix.','Verify the fixed release and investigate relevant logs/artifacts. A clean rescan does not rule out earlier compromise.'),
'0055':('Use composer why <reported-package> to identify the direct dependency bringing in the vulnerable transitive version. Upgrade the owning package to a compatible supported release or obtain a verified vendor fix.','Review composer.lock and integration tests, then confirm the deployed transitive version is outside the applicable advisory range.'),
'0056':('Compare the reported composer.json constraint and lockfile version with the advisory fixed range. Adjust the owning direct dependency constraint to a compatible supported version instead of bypassing the security restriction or editing composer.lock by hand.','Resolve dependencies in a branch, review the exact lockfile changes and test Magento compatibility before verifying the fixed deployed version.'),
'0057':('Check why the reported locked release was withdrawn and obtain vendor guidance. Move to a supported non-withdrawn compatible version, considering any integrity or security reason for withdrawal.','Verify the resolved artifact/source and deployed lockfile against current registry metadata; withdrawal alone is not a confirmed vulnerability.'),
'0058':('Inventory the affected Marketplace extension, installed version, support entitlement and vendor release notes. Plan the relevant maintained update and review license and compatibility requirements.','Test its Magento/PHP compatibility and business workflows and retain vendor lifecycle evidence, rather than relying only on a latest-version comparison.'),
'0059':('Confirm applicability and the publication age of each returned advisory. Assign an owner and deploy a supported fix according to the approved remediation deadline; Magebean observes a 30-day age threshold.','Verify the actual fix with fresh data. Publication age is not proof of how long this deployment was exposed or when the team first detected it.'),
'0060':('Obtain the vendor support policy and entitlement for each extension and compare them with the deployed version. Renew supported coverage, upgrade or replace unsupported critical extensions with an approved alternative.','Record vendor confirmation, version coverage and ownership; a reachable package repository is not support evidence.'),
'0061':('Review the abandoned package notice and recommended replacement. Identify usages with composer why, then migrate or remove the dependency in a compatibility-tested branch.','Confirm the deployed dependency graph no longer includes the abandoned package or retain a reviewed, time-limited maintained-fork exception.'),
'0062':('Review the reported latest release date and upstream maintenance evidence for the package. Check security support and compatibility before choosing a maintained replacement or upgrade; the 24-month threshold is Magebean maintenance policy.','Confirm current upstream metadata and vendor support. An old stable release date alone does not prove the installed package is vulnerable.'),
'0063':('Verify the reported source repository availability/archive state and identify the authoritative upstream or maintained replacement. Review whether support, release distribution or integrity is affected before changing repositories.','Retain current upstream evidence and test any replacement package; a network/API outage should be investigated as missing evidence, not abandonment.'),
'0064':('Review each fork, VCS repository override and replace/provide declaration in composer.json. Identify who maintains the fork, the upstream security patch process and the reason it replaces the original package.','Restore the supported upstream or approve a documented maintained fork and verify locked source references and security-update ownership.'),
'0065':('Replace the reported wildcard dependency constraints with explicit supported compatible release ranges based on vendor/Magento compatibility. Resolve and review composer.lock in a branch.','Verify constraints and locked versions after integration tests; a stricter range must still allow security updates.'),
'0066':('Replace the reported dev branch constraints with supported stable tagged releases where available. If a development reference is unavoidable, pin its immutable reference and document review, owner and expiry.','Verify reproducible dependency resolution and security-update handling; do not silently suppress stability checks.'),
'0067':('Review root composer.json stability policy and set prefer-stable to true when it matches the deployment policy. Remove unnecessary minimum-stability:dev and review explicit exceptions.','Resolve dependencies in a branch and confirm the lockfile selects approved releases; prefer-stable alone does not prohibit all development dependencies.'),
'0069':('Review the reported direct dependency against vendor support, compatibility and release notes. Upgrade where appropriate through a tested dependency update, or document why the current supported version is intentional.','Verify the deployed lockfile and current metadata. Being behind the latest release is maintenance information, not automatically a security vulnerability.'),
'0070':('Compare composer.json with composer.lock and identify mismatched content hashes, duplicate identities or missing dependency resolution. Regenerate the lockfile through Composer in a reviewed build environment, never by editing hashes manually.','Run composer validate and a reproducible composer install from the committed lockfile; test the resulting Magento release.'),
'0072':('Treat each reported VCS secret match as a candidate and verify it without copying its value into a ticket. Revoke/rotate confirmed credentials at their issuer, update protected deployment secrets and investigate repository exposure.','Remove the secret from active files and coordinate any approved history rewrite with repository owners; deleting a commit or string does not revoke an exposed credential.'),
'0073':('Locate each reported integration endpoint and replace it with the vendor-supported HTTPS URL. Configure trust validation and redirect handling in the actual client and review environment-specific endpoint overrides.','Test the integration against the intended hostname and trust chain; do not disable peer verification to make the request succeed.'),
'0075':('Identify the webhook provider and implement its documented signature scheme over the exact raw body, timestamp and event identifier. Store the verification secret securely, use constant-time comparison and reject stale/replayed events.','Test valid, modified, unsigned, expired and duplicate events in staging; a signature-related source keyword does not prove validation executes before side effects.'),
'0076':('Inventory required outbound destinations and define explicit application and network egress rules for their hosts, protocols and ports. Remove broad outbound access and protect DNS/redirect resolution from bypass.','Test approved integrations and denied internal/unapproved destinations; retain effective firewall/proxy rules in addition to source observations.'),
'0077':('Trace the third-party payload and remove fields not required for its stated business purpose. Mask or tokenize sensitive identifiers and review consent, retention and vendor access with the data owner.','Inspect a redacted representative outbound payload and vendor retention evidence; comments or field names in source do not establish minimization.'),
'0078':('Identify the real TLS termination point for each reported gateway and apply the supported strong cipher/protocol policy there. Review nginx/Apache/load-balancer inheritance and required payment clients.','Probe the live gateway for negotiated protocols/ciphers and trust; a repository configuration file alone cannot establish the effective upstream policy.'),
'0079':('Remove API keys from custom source or unprotected configuration storage and use the approved deployment secret mechanism. Where appropriate use protected env.php integration configuration or a managed secret store; rotate confirmed exposed values.','Verify the integration still works and secrets are excluded from Git, exports, logs and public endpoints. env.php presence alone does not prove safe secret handling.'),
'0081':('Review the SaaS integration account/token, Magento ACL grants and provider-side network restrictions. Limit privileges to the required resources and revoke unnecessary scopes or unused credentials.','Test authorized operations and denied unrelated resources and retain effective provider and Magento grant evidence.'),
'0082':('Identify the database fields, encryption model and payment-provider data flow behind each observation. Remove unnecessary PAN and prohibited sensitive authentication data using an approved data-retention/migration procedure and move collection to the provider where appropriate.','Have the payment/security owner verify live and backup data handling with redacted evidence. Source strings do not prove actual database contents or PCI compliance.'),
'0083':('Identify affected files, exports and backups and restrict access immediately. Remove unnecessary payment data under the approved retention and incident process; use provider tokens rather than raw account data.','Verify export behavior, backup retention and restoration paths with the payment/data owner; do not publish raw payment data as evidence.'),
'0085':('Create an inventory of enabled payment methods, owners, provider integrations and data flows across browser, Magento, webhooks and third parties. Record which systems receive account data and who confirms scope.','Validate the inventory against actual checkout/network behavior and vendor documentation; this Magebean check does not determine formal PCI scope.'),
'0086':('Review each raw card input or payment payload in Magento checkout. Prefer a supported hosted/redirected or provider-hosted field integration, and remove unnecessary card handling from Magento application code.','Use provider test data in staging to trace browser/server flows and confirm Magento logs/storage do not receive prohibited card data; obtain payment-scope review.'),
'0087':('Maintain an owned inventory of scripts executed on payment pages, including third-party sources, purpose, approval and change process. Remove unauthorized or unnecessary scripts.','Compare the inventory with real checkout network execution and deployment changes; a static source list misses injected or dynamically loaded scripts.'),
'0088':('Approve only necessary payment-page scripts and implement suitable origin restrictions, integrity controls and change approval for the integration architecture. Coordinate restrictions with payment vendors and Magento CSP.','Test the complete checkout flow and demonstrate an unauthorized script change is detected or blocked; source allowlists alone are insufficient.'),
'0089':('Review Magento CSP configuration for the actual checkout routes and version. Enforce a restrictive script policy with supported nonces/hashes and explicit required origins instead of broad wildcards or report-only protection.','Inspect the enforced response header and browser violations on checkout, including payment return/3DS flows; an XML declaration alone does not prove runtime enforcement.'),
'0090':('Implement independent payment-page tamper monitoring with an owner, approved baseline, review schedule and alert routing. Cover browser-delivered scripts and relevant security headers, not only source repository changes.','Perform an approved staging change and verify detection, notification and response evidence; a monitoring configuration file is only readiness evidence.'),
'0092':('Validate payment webhook provider signatures, timestamps and event IDs before updating orders. Add replay protection, idempotency and strict event/order validation; avoid treating an obscure URL or IP header as authentication.','Test invalid signatures, modified payloads, stale timestamps and duplicate/out-of-order events using the provider sandbox.'),
'0093':('Assign an owner to the payment/security evidence checklist and collect scope, responsibility, access, monitoring and recovery artifacts relevant to the actual payment architecture. Track missing evidence explicitly.','Have the appropriate assessor/reviewer evaluate the artifacts against the separate PCI profile; a Magebean checklist does not establish PCI compliance.'),
'0094':('Trace each custom controller/API action to its authorization decision. Require the supported Magento ACL or authenticated resource permission and verify ownership/tenant boundaries before reading or changing protected objects.','Test anonymous, low-privilege and cross-account access in staging; finding an ACL string does not prove the check is executed on every path.'),
'0095':('Inventory public REST/GraphQL operations and intended anonymous access. Remove unnecessary exposure and enforce authentication, object authorization, query limits and appropriate rate controls without breaking documented public storefront operations.','Test anonymous and low-privilege requests against sensitive fields/actions; introspection visibility alone is not proof of a vulnerability.'),
'0096':('Inspect the effective response headers at the CDN/proxy/application boundary. Configure appropriate enforced CSP/framing, nosniff and transport policies for the actual routes, avoiding duplicate or contradictory headers.','Verify successful storefront, Admin and checkout responses and browser behavior; repository declarations or a generic error page are not runtime proof.'),
'0097':('Verify candidate hardcoded credentials privately and revoke/rotate confirmed exposed values. Move required secrets to the approved protected deployment mechanism and remove them from custom source and build artifacts.','Rescan the deployed files and repository history and verify the old credential is rejected; never paste the secret into remediation tickets.'),
'0098':('Review the XML parser invocation and trust boundary. Disable external entity/network/DTD resolution for untrusted XML and use the supported safe parsing configuration; avoid LIBXML_NOENT on untrusted input.','Test controlled external entity and malformed/oversized XML cases without contacting real internal services, and verify normal required documents still parse.'),
'0099':('Identify each download/export endpoint and require authentication, explicit resource permission and object ownership checks before streaming data. Generate safe filenames and enforce path containment.','Test anonymous, low-privilege, other-customer and traversal requests in staging; verify unauthorized requests return no protected file contents.'),
'0100':('Review the reported user_id, role_id and relational finding type in Magento Admin users/roles. Repair missing groups, orphan references or cyclic ancestry through the supported administration workflow, not ad hoc ACL SQL.','Confirm each active account has a valid intended role with ACL rules and rerun the relationship check. Separately review business approval and least privilege.'),
'0101':('Review every role/account with global or wildcard Admin resources against documented business approval. Replace unnecessary global grants with narrowly required resources and remove unused privileged accounts.','Test required and denied Admin actions as affected users and retain approval evidence; an empty approval list must not be treated as a universal ban on all administrators.'),
'0102':('Inventory vendor-provided/default accounts for the assessed components and compare them with deployment evidence. Disable/remove unused defaults or change default credentials through each vendor-supported procedure.','Verify unauthorized/default login is rejected using designated test accounts and retain inventory evidence; source package names cannot establish live account state.'),
'0728':('Review the resolved Magento Admin minimum password length and installed validation rules. Configure or implement the supported organizational policy for the installed version; Magebean uses at least eight characters.','Test rejection of too-short new passwords and compatibility with existing authentication/IMS policy. Do not assume this configuration retroactively proves existing password strength.'),
'0729':('Disable the reported project/default-scope debug, template hint or error-display setting through the managed deployment configuration. Inspect the real PHP-FPM/web worker and store overrides separately.','Reload/redeploy through the approved process and verify successful pages do not disclose debug output; CLI ini settings alone are not web-worker proof.'),
'0730':('Review each redacted deployed-file secret-pattern match and privately confirm whether it is a real credential. Revoke/rotate exposed secrets and move them to the approved deployment secret mechanism.','Rescan readable deployed scope and investigate any public/Git exposure. Pattern absence does not prove env.php is protected or that historical copies are safe.'),
'0731':('Review the installed native Admin password validator and any customization. Apply the approved minimum-length policy using the supported version-specific mechanism and retain evidence for external identity-provider policy where applicable.','Test new-password rejection/acceptance with designated accounts; source/module defaults alone do not establish the strength of existing passwords.'),
'0732':('Trace the reported SQL construction and replace concatenated user values with parameterized queries through supported Magento resource connections, collections or repositories. Allow-list dynamic identifiers separately; placeholders do not bind table/column names.','Test quotes, unexpected types and unauthorized object access in staging and verify query bindings. Raw SQL presence alone is not proof of exploitable injection.'),
'0733':('Identify the output context at each reported template line. Use the appropriate Magento Escaper method for HTML text, attributes or URLs and keep deliberately trusted HTML narrowly justified; do not apply one escape method to every context.','Test representative untrusted input in the actual page and confirm it is displayed as data without executable markup; review double-escaping regressions.'),
'0734':('Remove unserialize of untrusted input and use a supported JSON/typed serialization format. If compatibility requires legacy serialized data, enforce a reviewed trusted-data boundary and restrictive class policy as a temporary measure.','Test tampered input and confirm no attacker-controlled object instantiation or magic method side effects; keyword absence alone is not data-flow proof.'),
'0735':('Remove unnecessary shell/process execution from the reported path and prefer supported library/service APIs. If execution is required, use a fixed binary and structured argument list with strict allow-lists and a low-privilege process.','Test controlled metacharacters and unexpected arguments in staging; escaping one argument does not make an attacker-controlled command string safe.'),
'0736':('Review the exact JavaScript/HTML embedding context. Serialize data with the supported JSON mechanism and appropriate script-context protections; avoid string concatenation into executable JavaScript or event-handler attributes.','Test quotes, closing script delimiters and markup in the actual template using inert test data and verify no script execution or broken syntax.'),
'0737':('Locate the logger call and payload source. Remove passwords, session tokens, authorization headers and unnecessary personal/payment data; log minimal identifiers and redact structured fields before serialization.','Inspect redacted representative application and central-log events and verify sensitive values do not appear in exception or debug paths.'),
'0738':('Disable Xdebug in the production PHP-FPM/web worker and CLI where applicable using the deployed PHP configuration. Restrict any intentional debugging environment to authorized access and a time-limited change.','Verify the effective worker configuration and successful HTTP responses after reload; a CLI php -m result alone does not prove every worker is protected.'),
'0739':('Set display_errors Off in the actual production PHP worker and keep error reporting in private logs with appropriate access. Correct application exception handling so responses do not expose stack traces or configuration.','Test a controlled staging exception and inspect the response and private log; normal 200 pages alone do not exercise failure disclosure.'),
'0740':('Disable frontend/Admin template hints and related developer flags in the correct store scope and managed configuration. Review env/config/database precedence and protected cache invalidation.','Inspect affected storefront/Admin pages after deployment and verify hints are absent across intended stores.'),
'0741':('Review whether the reported file cache backend is intentional for this deployment. Configure the supported production cache backend and appropriate network/authentication boundary, or record an approved architecture exception.','Test cache connectivity, invalidation and release behavior; do not treat a backend name alone as a confirmed exploitable vulnerability.'),
'0742':('Disable the specific developer/debug configuration reported for production, including template hints and store-scoped overrides. Apply the change through the deployment owner workflow rather than editing generated files.','Verify effective configuration and browser pages for each affected store/worker after deployment.'),
'0743':('Remove unnecessary personal data from the reported log statement and apply structured redaction before writing logs. Review centralized log retention, access and historical exposure with the data owner.','Inspect representative redacted events from success and exception flows and confirm retention/access controls match policy.'),
'0744':('Identify consumers of the abandoned dependency with composer why and review the upstream replacement. Migrate/remove it through a compatibility-tested dependency update or document a maintained-fork exception with an owner.','Verify the deployed lockfile and support evidence and rerun fresh metadata checks; abandonment does not itself prove a CVE.'),
'0745':('Review debug/verbose flags in each third-party integration and disable them for production unless a tightly controlled diagnostic window is approved. Ensure secrets and payloads are not dumped into logs or responses.','Exercise normal and error integration paths and inspect redacted logs and runtime configuration after the release.'),
'0746':('Locate third-party logger/client middleware and redact sensitive headers, tokens and personal/payment fields before payload serialization. Limit diagnostic logging and private retention to the minimum required.','Test representative integration failures and retries and confirm raw requests/responses do not leak protected values.'),
'0747':('Restrict access to affected logs and notify the payment/data owner if account data may have been retained. Remove payment-data logging, apply approved redaction and follow retention/incident procedures for historical copies.','Verify application, gateway and central logs using approved redacted evidence; do not attach real PAN or authentication data to tickets.'),
'0748':('Privately inspect the reported media/upload file without executing it and confirm whether it is authorized content or suspicious code. Quarantine suspicious artifacts under the incident process, remove unauthorized content and disable script execution in upload locations.','Verify no executable artifacts remain in the intended inventory and test server execution denial using an approved inert staging fixture; investigate how the file arrived.'),
'0773':('Enable Add Secret Key to URLs in native Admin Security or the equivalent managed admin/security/use_form_key configuration. Review custom Admin routes for bypass of the supported framework protection.','Verify the resolved value and an authenticated Admin workflow; URL keys complement rather than replace authorization and CSRF protection.'),
'0774':('Enable Case Sensitive Login in native Admin Security or managed admin/security/use_case_sensitive_login configuration. Check identity-provider applicability before changing an IMS deployment.','Use a designated staging account to verify the configured login behavior and confirm authorized login still works.'),
'0775':('Disable Admin Account Sharing in native Admin Security and provision individually owned administrator accounts with approved roles. Investigate shared credentials already in use and rotate them safely.','Verify the configured flag, account ownership and intended concurrent-session behavior; configuration alone cannot prove people do not share passwords.'),
'0776':('Enable Admin password reset protection and configure bounded requests plus cooldown in Admin Security. Review the finding values against the approved policy; Magebean defaults are at most five requests/hour and at least one minute between requests.','Test controlled staging resets for valid users, excessive requests and recovery success without sending unsolicited production reset emails.'),
'0777':('Resolve the actual Admin route and TLS termination layer. Configure its HTTP entrypoint to redirect directly to same-host HTTPS and correct Magento secure Admin/proxy configuration.','Probe that exact Admin entrypoint and verify authenticated login/session behavior; storefront redirect evidence does not cover a different Admin origin.'),
'0778':('Inspect the certificate served for the reported hostname at the CDN/load balancer/origin. Renew/reissue the correct certificate and deploy the complete trusted chain; review automation before the Magebean 15-day renewal margin is reached.','Verify hostname, current validity and chain from the scanner environment and intended clients. Install an approved private CA when appropriate; never disable verification as a fix.'),
'0779':('Set an enforced restrictive CSP frame-ancestors policy on the affected page, or valid X-Frame-Options where no enforced frame-ancestors overrides it. Remove broad schemes/wildcards and contradictory duplicate directives after reviewing intended embedding.','Inspect the successful response and test authorized/unauthorized framing in a browser. Enforced frame-ancestors takes precedence over X-Frame-Options.'),
'0780':('Inspect the reported PHP-like media filenames privately without executing them. Quarantine unauthorized content and review upload validation and server execution denial; distinguish legitimate reviewed artifacts from compromise indicators.','Rerun the complete media filename inventory and test execution denial with an approved inert staging fixture. Filename absence alone is not server policy proof.'),
'0781':('At the effective document root, origin and CDN deny the specific artifact paths reported exposed. Move deployment configuration, Git metadata and logs out of public aliases and clear cached copies where needed.','Verify the six named paths return denial/absence without credentials; rotate exposed secrets and investigate access history if a real artifact signature was served.'),
'0782':('Privately confirm whether app/etc/env.php is tracked using git ls-files --error-unmatch -- app/etc/env.php. Remove it from the index through a reviewed repository change while preserving required local deployment configuration and adding the ignore rule.','Rotate any credentials committed to the repository and review historical/remote exposure; verify the current index no longer contains the file. No Git index means separate deployment evidence is needed.'),
'0783':('Configure a supported every-minute Magento cron:run schedule for the correct deployment user, PHP binary and release path, or provide equivalent Cloud/container scheduler evidence. Review duplicate schedulers before adding another entry.','Verify the installed cadence and recent execution records. A yearly/daily entry is not an every-minute schedule, and scheduler presence does not prove jobs succeed.'),
'0784':('Identify the intended themes/locales and the published scope missing CSS/JS. Rebuild and deploy static content for the required release scopes through the supported pipeline; document headless, inline or alternative asset delivery explicitly.','Request representative page-referenced assets and verify nonempty correct content after cache invalidation; discovered published scopes do not prove active-store completeness.'),
'0785':('Inspect cron_schedule successes and overdue pending jobs by job_code and timestamps. Repair scheduler connectivity, failing workers or resource contention before changing capacity; do not delete records just to hide backlog.','Confirm a success within the configured 24-hour window and no pending jobs older than 15 minutes, then review missed/error jobs and critical job groups separately.'),
}
catalog=json.loads((base/'magebean-catalog.json').read_text())
assert set(recipes)=={r['id'][3:] for r in catalog['requirements']}, 'Every Magebean requirement needs an individually reviewed recipe'
security='https://experienceleague.adobe.com/en/docs/commerce-operations/implementation-playbook/best-practices/launch/security-best-practices'
dev='https://developer.adobe.com/commerce/php/development/security/'
risks={
 'MB-C01':'If an unauthorized party can write deployed code or retrieve sensitive artifacts, the boundary failure can expose credentials/data or permit application modification. Filename, mode and placement observations must be checked against effective access and serving policy.',
 'MB-C02':'Weak or incorrectly scoped administrative controls can increase unauthorized access, account takeover or privileged misuse risk. Configuration alone does not prove a successful bypass or effective protection for every account.',
 'MB-C03':'If client-controlled data reaches a sensitive operation without appropriate validation, authorization or context-specific handling, application data or execution may be affected. Source patterns require data-flow and runtime confirmation.',
 'MB-C04':'A transport or browser-policy gap can weaken protection against interception, session exposure or unwanted browser execution/framing on the affected flow. Confirm the real endpoint, trust boundary and browser behavior.',
 'MB-C05':'Inconsistent production builds or debug settings can cause failed application workflows or disclose implementation details. Deployment readiness failures should not automatically be described as exploitable vulnerabilities.',
 'MB-C06':'Incorrect cache, indexing or session-backend configuration can impair availability, consistency or session protection. Assess the actual backend and data separation; declarations alone do not establish runtime behavior.',
 'MB-C07':'Uncontrolled diagnostic data, monitoring gaps or missing operational evidence can increase data exposure or delay detection/recovery. Assess the specific artifact and workflow rather than inferring effectiveness from source markers.',
 'MB-C08':'Missing or unhealthy scheduled execution can delay indexing, email, cleanup and other required jobs. This is an operational readiness signal; scheduler presence alone does not prove successful job execution.',
 'MB-C09':'An applicable unfixed advisory or unsupported component can leave the deployment exposed to a known issue. Confirm affected ranges, edition, reachable functionality and verified vendor fixes before assigning the actual exposure.',
 'MB-C10':'Unmaintained or diverted upstream dependencies can slow security fixes and weaken maintenance provenance. Age, archive or abandonment metadata alone is not proof of an exploitable vulnerability.',
 'MB-C11':'Uncontrolled dependency resolution or lifecycle policy can make builds less reproducible and delay safe updates. Verify the resolved artifacts and supported versions rather than equating every maintenance deviation with a vulnerability.',
 'MB-C12':'Integration trust-boundary failures can expose secrets/personal or payment data, allow forged events or permit unintended outbound access. Confirm the concrete data flow and provider-side controls; source observations are not payment-scope certification.',
}
specific={
 'MB-0014':'Direct superglobal access can bypass framework input conventions and make validation or trust assumptions difficult to audit. Risk depends on what the value controls: an unvalidated SQL/path/network/output sink is materially different from a validated value or trusted bootstrap metadata.',
 'MB-0006':'A common Admin route makes discovery easier but changing its name does not prevent authentication bypass or unauthorized access. MFA, authorization and access restrictions remain the substantive controls.',
 'MB-0015':'A state-changing session request without effective CSRF validation may let another site trigger actions under an authenticated user. A token appearing in source is not proof it is validated.',
 'MB-0016':'A user-controlled outbound destination may let the server access internal services or metadata, or exfiltrate responses, if host/address/redirect policy is bypassable.',
 'MB-0019':'Attacker influence over dynamically executed PHP can allow arbitrary application-level code execution. Reachability and input control must be confirmed before making that claim.',
 'MB-0020':'A path escaping its intended base directory can allow unauthorized file reads or writes, depending on the operation and process permissions.',
 'MB-0021':'Insufficient upload validation or executable storage can permit malicious content delivery or server-side execution. Extension matches alone do not demonstrate that uploaded code executes.',
 'MB-0023':'Predictable security tokens or identifiers can make guessing or collisions feasible. Ordinary non-security randomness has a different impact and should be assessed separately.',
 'MB-0030':'An insufficiently protected sensitive cookie may be exposed to cleartext transport, unintended script access or cross-site use. Required attributes depend on the actual cookie purpose and browser flow.',
 'MB-0732':'Concatenating untrusted values into SQL can permit query manipulation; raw SQL with correct bindings and authorization has a different risk. The observation needs parameter and reachability review.',
 'MB-0733':'Untrusted template data rendered without context-appropriate escaping can execute browser markup/script or alter attributes. Trusted HTML and already-escaped values require deliberate contextual review.',
 'MB-0734':'Deserializing attacker-controlled PHP objects can invoke dangerous object behavior if suitable classes and runtime paths exist. A serializer call alone is not a complete exploitation proof.',
 'MB-0735':'Untrusted command strings or arguments can change the executed process behavior, potentially reaching code execution with the application identity.',
 'MB-0736':'Untrusted data concatenated into JavaScript or HTML script contexts can break out into executable script. HTML escaping alone may not protect a JavaScript context.',
 'MB-0779':'An attacker may frame an insufficiently protected sensitive page and trick a user into unintended actions. Intended embedding and actual browser enforcement determine applicability.',
}
for r in catalog['requirements']:
    change,verify=recipes[r['id'][3:]]
    previous=r.get('remediation',[])
    r['remediation']=['Investigate and change: '+change,'Validate the change: '+verify,'Recheck: rerun '+r['id']+' on the same release, target mode and relevant runtime URL; compare the new evidence with this result. Retain the original result and document any approved exception with owner and expiry.']
    if previous and previous!=r['remediation'] and not r.get('remediation_history'):
        r['remediation_history']=[{'guidance_version':0,'instructions':previous}]
    source_observation=any(c['name'].startswith('code_') for c in r.get('checks',[]))
    r['finding_guidance']={
        'version':1,
        'interpretation':('This is a source observation or development-policy condition. Confirm the trust boundary, runtime path and compensating controls before claiming an exploitable vulnerability.' if source_observation else 'Interpret the result against the exact criterion, observed deployment scope and configured policy. A failed observation does not by itself establish exploitation or the state of unobserved environments.'),
        'risk':specific.get(r['id'],risks[r['control']]),
        'triage':['Identify the affected resource and observed value in the check evidence; record the release, target and collection time.','Compare the evidence with the requirement criterion and deployment architecture. If evidence is missing or incomplete, collect it before deciding whether a violation or justified exception exists.'],
        'verification':[verify,'Rerun '+r['id']+' and retain the new result; do not close solely because the configuration file or ticket was updated.'],
        'limitations':r['human_evidence'].get('instructions') or 'This check covers only the collected observation. Missing collection scope, external controls and runtime behavior require separate evidence.',
        'references':list(dict.fromkeys(r.get('guidance_sources',[])+[dev if source_observation else security])),
    }
    if r['id']=='MB-0014':
        r['finding_guidance']['interpretation']='Direct PHP superglobal tokens violate the scoped Magebean development policy, but do not by themselves demonstrate SQL injection, XSS, authorization bypass or another exploitable vulnerability. RequestInterface is an input-access abstraction, not a validation or authorization boundary.'
        r['finding_guidance']['triage']=['Open each reported file:line and identify the superglobal variable and the component handling it.','Trace whether the value is client-controlled, validated, authorized and used by a SQL, HTML/JavaScript, file/path or outbound-request sink.','Distinguish HTTP controllers from CLI/bootstrap code and trusted server metadata. Confirm actual reachability and keep any narrow exception documented.']
        r['finding_guidance']['references']=[dev,'https://developer.adobe.com/commerce/php/coding-standards/technical-guidelines','https://developer.adobe.com/commerce/php/best-practices/extensions/security']
aggregate=json.loads((base/'internal-catalog.json').read_text()); index={r['id']:r for r in catalog['requirements']}
aggregate['requirements']=[index.get(r['id'],r) for r in aggregate['requirements']]
for name,value in [('magebean-catalog',catalog),('internal-catalog',aggregate)]:
    (base/(name+'.json')).write_text(json.dumps(value,indent=2,ensure_ascii=False)+'\n')
print('Added individually reviewed remediation and structured finding guidance to',len(recipes),'Magebean requirements; ASVS/PCI unchanged.')
